/* Teaching support is deliberately presentation-only: it guides users to the
   declared Software I workflow without changing the governing routing core. */
(() => {
  const isZh=()=>document.documentElement.lang==='zh-Hant';
  const copy=()=>isZh()?{
    title:'教學輔助｜四步自學與立即檢核',
    lead:'依序完成物理條件、執行路由、讀取判讀與確認篩選資格。教學提示不會修改 RK4 路由方程，也不會將 176 組回歸擴大解釋為通用設計驗證。',
    start:'載入可執行受限篩選教學案例（先保存目前案例）', restore:'還原先前案例',reset:'重新檢核',
    steps:[['1','定義事件入流','選擇三角形或長延時入流；尖峰流量之外，歷線延時與形狀也會影響滯洪量。','mod-inflow'],['2','宣告蓄水與出口','確認 S(H)、初始水位與啟用出口的高程採用相同基準。','mod-storage'],['3','執行並解讀結果','先看質量平衡、最大水位、尖峰出流與寬峰時間判讀。','mod-routing'],['4','判斷是否可篩選','受限篩選須確認自由出流，且僅限單一被動堰流或矩形開口；它不是通用的最終工程設計驗證。','mod-optimization']],
    checks:'快速自我檢核（每題約 30 秒）', score:'已答對 {n}/3 題',
    q:[['哪一項最直接決定池內蓄水量的時間變化？',['只有入流尖峰','Qin − Qout','只有池面積'],'Qin − Qout','連續方程以 Qin − Qout 控制蓄水變化。'],['對同一入流尖峰，何者仍可能改變滯洪需求？',['歷線延時與形狀','只有圖表顏色','報告檔名'],'歷線延時與形狀','正確；入流體積、歷線形狀與出口水理都會影響反應。'],['何時不得進行受限設計篩選？',['已確認自由出流的矩形孔口','使用豎井、圓管或複合出口的研究模式','已驗證的被動堰流'],'使用豎井、圓管或複合出口的研究模式','正確；此類設定僅供研究檢視，須獨立驗證後才能作設計使用。']],
    done:'完成', go:'前往步驟', demo:'已載入可執行的受限篩選教學案例，原案例已暫存。自由出流勾選與兩項紀錄均為教學假設，只可用來學習操作；實際工程必須以圖說、現地檢查與設計準則重新填寫。',confirm:'載入教學案例會暫時取代目前輸入，並帶入僅供練習的自由出流假設與限制依據；已先保存目前案例。要繼續嗎？',restored:'已還原載入教學案例前的案例。'
  }:{
    title:'Teaching support | four-step self-learning',
    lead:'Define physical conditions, run the route, interpret the record, and then check screening eligibility. Teaching prompts never change the RK4 governing equation or convert the 176-case regression into universal design validation.',
    start:'Load teaching example (save current case)',restore:'Restore previous case',reset:'Recheck',
    steps:[['1','Define event inflow','Choose a triangular or long-duration event. Duration and shape, not peak flow alone, affect detention storage.','mod-inflow'],['2','Declare storage and outlets','Use one vertical datum for S(H), the initial level, and every active outlet elevation.','mod-storage'],['3','Run and interpret','Read mass balance, maximum level, peak outflow, and broad-crest timing interpretation first.','mod-routing'],['4','Check screening eligibility','Constrained screening requires confirmed free discharge and a single passive weir or rectangular opening. It is not universal final-design validation.','mod-optimization']],
    checks:'Quick self-check (about 30 seconds each)',score:'{n}/3 correct',
    q:[['Which term directly controls the time change of pond storage?',['Inflow peak alone','Qin − Qout','Plan area alone'],'Qin − Qout','The continuity equation changes storage by Qin − Qout.'],['For the same inflow peak, what can still change detention demand?',['Hydrograph duration and shape','Chart colour','Report filename'],'Hydrograph duration and shape','Correct. Inflow volume, hydrograph shape, and outlet hydraulics affect the response.'],['When is constrained design screening unavailable?',['Confirmed free-discharge rectangular opening','Research-mode riser, pipe, or composite outlet','Validated passive weir'],'Research-mode riser, pipe, or composite outlet','Correct. These modes are for research inspection until independently validated.']],
    done:'Done',go:'Go to step',demo:'Triangular demonstration loaded and your working case is saved. Free discharge is not confirmed in the demonstration; complete the evidence checks before deciding whether constrained screening is available.',confirm:'Loading the teaching example temporarily replaces the current inputs. Your working case will be saved first. Continue?',restored:'The case from before the teaching demonstration has been restored.'
  };
  const host=document.querySelector('.module-workspace')||document.querySelector('main.wrap'); if(!host) return;
  const panel=document.createElement('section'); panel.id='teachingAssistant'; panel.className='panel';
  host.insertBefore(panel,host.firstChild);
  const style=document.createElement('style'); style.textContent=`#teachingAssistant{margin:0 0 18px;border-top:5px solid #7c3aed;background:linear-gradient(135deg,#fbfaff,#f3f8ff)}#teachingAssistant h2{font-size:21px}.teach-lead{max-width:900px;color:#38536a;margin:0 0 14px}.teach-outlet{border:1px solid #c4b5fd;background:#fff;padding:12px;border-radius:7px;color:#312e81}.teach-outlet p{font-size:14px;margin:6px 0}.teach-outlet code{font-size:15px;color:#102a43}.teach-top{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap}.teach-button{border:0;background:#7c3aed;color:#fff;border-radius:5px;padding:9px 13px;font-weight:700;cursor:pointer}.teach-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:16px 0}.teach-step{border:1px solid #d8c9f5;background:#fff;border-radius:7px;padding:12px;min-height:156px}.teach-step b{display:inline-grid;place-items:center;width:25px;height:25px;border-radius:50%;background:#ede9fe;color:#6d28d9;margin-right:6px}.teach-step h3{display:inline;color:#312e81}.teach-step p{font-size:13px;color:#526a78;margin:9px 0 12px}.teach-go{border:1px solid #7c3aed;background:#fff;color:#5b21b6;border-radius:4px;padding:6px 8px;cursor:pointer;font-weight:700}.teach-quiz,.teach-functions{border-top:1px solid #d8c9f5;padding-top:14px;margin-top:14px}.teach-quiz h3,.teach-functions h3{margin:0 0 10px;color:#312e81}.quiz-grid,.function-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.quiz-card,.function-card{background:#fff;border:1px solid #d8c9f5;border-radius:7px;padding:12px}.quiz-card p,.function-card strong{font-weight:700;font-size:14px;margin:0 0 8px}.function-card p{font-size:13px;color:#526a78;margin:7px 0 0}.quiz-card label{font-weight:400;display:flex;gap:7px;align-items:flex-start;cursor:pointer}.quiz-card input{width:auto;margin-top:3px}.quiz-feedback{font-size:13px;margin-top:8px;color:#526a78}.quiz-feedback.ok{color:#166534;font-weight:700}.quiz-feedback.bad{color:#9a5a00}.teach-score{font-size:13px;font-weight:700;color:#5b21b6}.teach-note{font-size:13px;color:#526a78;margin:8px 0 0}@media(max-width:850px){.teach-steps,.quiz-grid,.function-grid{grid-template-columns:1fr}}`; document.head.appendChild(style);
  let savedCase=null;
  const workspace=()=>document.querySelector('.module-workspace')||document.querySelector('.grid .panel');
  function snapshot(){return [...workspace().querySelectorAll('input,select,textarea')].filter(x=>x.id).map(x=>({id:x.id,checked:x.checked,value:x.value,kind:x.type}));}
  function restore(snapshot){snapshot.forEach(v=>{const el=document.getElementById(v.id);if(!el)return;if(v.kind==='checkbox'||v.kind==='radio')el.checked=v.checked;else el.value=v.value;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));});}
  function navButton(){const nav=document.getElementById('moduleNavContent');if(!nav||document.getElementById('teachingNavButton'))return;const b=document.createElement('button');b.id='teachingNavButton';b.className='module-link';b.textContent=isZh()?'教學輔助｜四步自學':'Teaching support | four-step learning';b.addEventListener('click',()=>panel.scrollIntoView({behavior:'smooth',block:'start'}));nav.insertBefore(b,nav.querySelector('.module-link')||nav.firstChild);}
  function downloadPractice(){const text=['Software I 實驗練習案例｜三角形入流、銳頂堰與受限篩選','用途：重現本研究過去實驗設定所整理的教學操作案例。','限制：此檔案不是 176 組固定實驗回歸的原始觀測資料，也不得作為通用設計驗證。','','[入流設定]','案例：三角形事件','入流尖峰 Qp = 0.120 m³/s','洪峰到達時間 Tp = 30 min','退水時間 Tr = 30 min','','[蓄水設定]','平面面積 A = 180 m²','初始水位 H0 = 0.00 m','','[出口流量關係]','啟用出口：單一銳頂堰（被動、自由出流的教學假設）','Qout(H) = Cw × b × max(H − P, 0)^(3/2)','Cw = 1.70；堰寬 b = 0.20 m；堰頂高程 P = 0.00 m','例如 H = 0.50 m 時，Qout = 1.70 × 0.20 × 0.50^(3/2) = 0.1202 m³/s。','','[受限篩選練習限制]','Qallow = 0.080 m³/s；Hallow = 1.00 m；其餘排空限制依畫面設定。','自由出流四項勾選與兩項可追溯紀錄僅為教學假設；實際工程必須以圖說、現地檢查與設計準則重新填寫。','','[練習任務]','1. 載入案例並確認 Qin、Qout、水位與蓄水量圖。','2. 執行受限篩選，閱讀可行或不可行結果；不可行時不可選取違反限制的方案。','3. 比較相同尖峰流量下，延長歷線時間後的滯洪需求。'].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='Software-I-實驗練習案例-三角形入流.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),0);}
  function render(){const t=copy(),functions=isZh()?[['入流邊界','定義事件的尖峰、上升、平頂與退水歷線；不可只用尖峰流量代表滯洪需求。'],['蓄水量—水位狀態','以固定面積或表列 S(H) 連結蓄水量與水位，並使用同一高程基準。'],['出口水理','設定被動堰流或矩形開口及係數；尾水、回水、淹沒與操作控制須由使用者提出證據。'],['第一性原理路由','以 dS/dt = Qin − Qout 和 RK4 逐時演算，檢查質量平衡。'],['受限設計篩選','只在單一被動堰流或單一矩形開口、自由出流證據完整時開放；結果不是最終設計。'],['評估與決策支援','閱讀尖峰削減、滯洪量、時間指標與可追溯紀錄，並保留工程判讀依據。']]:[['Inflow boundary','Define the event peak, rise, plateau and recession; peak flow alone does not represent detention demand.'],['Storage–level state','Use constant area or tabulated S(H) with one consistent datum.'],['Outlet hydraulics','Declare passive outlets and coefficients; users must document tailwater, backwater, submergence and operation.'],['First-principles routing','Solve dS/dt = Qin − Qout with RK4 and inspect mass balance.'],['Constrained screening','Available only for one passive weir or one rectangular opening with complete free-discharge evidence; it is not final design.'],['Evaluation and support','Read attenuation, storage, timing and traceability records as the engineering decision basis.']];const outlet=isZh()?'<div class="teach-outlet"><strong>教學案例的出口流量關係 Qout(H)</strong><p>啟用單一銳頂堰：<code>Qout(H) = Cw × b × max(H − P, 0)<sup>3/2</sup></code></p><p>Cw = 1.70、b = 0.20 m、P = 0.00 m；例如 H = 0.50 m 時，Qout = 0.1202 m³/s。此式只在自由出流的教學假設下使用。</p></div>':'<div class="teach-outlet"><strong>Teaching-case outlet relation Qout(H)</strong><p>One sharp-crested weir: <code>Qout(H) = Cw × b × max(H − P, 0)<sup>3/2</sup></code></p><p>Cw = 1.70, b = 0.20 m, P = 0.00 m; at H = 0.50 m, Qout = 0.1202 m³/s. This relation applies only under the teaching free-discharge assumption.</p></div>';panel.innerHTML=`<div class="teach-top"><h2>${t.title}</h2><div><span id="teachScore" class="teach-score">${t.score.replace('{n}','0')}</span> <button id="teachPractice" class="teach-go">${isZh()?'下載實驗練習案例':'Download practice case'}</button> <button id="teachDemo" class="teach-button">${t.start}</button> <button id="teachRestore" class="teach-go" ${savedCase?'':'disabled'}>${t.restore}</button></div></div><p class="teach-lead">${t.lead}</p>${outlet}<div class="teach-steps">${t.steps.map(s=>`<article class="teach-step"><b>${s[0]}</b><h3>${s[1]}</h3><p>${s[2]}</p><button class="teach-go" data-target="${s[3]}">${t.go}</button></article>`).join('')}</div><div class="teach-functions"><h3>${isZh()?'Software I 各功能說明':'Software I feature guide'}</h3><div class="function-grid">${functions.map(f=>`<article class="function-card"><strong>${f[0]}</strong><p>${f[1]}</p></article>`).join('')}</div><p class="teach-note">${isZh()?'練習案例為過去實驗設定的教學化重現；不含 176 組固定回歸的原始資料。':'The practice case is a teaching reconstruction of prior experimental settings; it excludes the 176-case raw regression data.'}</p></div><div class="teach-quiz"><h3>${t.checks}</h3><div class="quiz-grid">${t.q.map((q,i)=>`<article class="quiz-card" data-answer="${q[2]}"><p>${i+1}. ${q[0]}</p>${q[1].map(a=>`<label><input type="radio" name="teach-q${i}" value="${a}">${a}</label>`).join('')}<div class="quiz-feedback" data-note="${q[3]}"</div></article>`).join('')}</div></div>`;
    const quizHost=panel.querySelector('.teach-quiz');quizHost.innerHTML='<h3>'+t.checks+'</h3><div class="quiz-grid">'+t.q.map((q,i)=>'<article class="quiz-card" data-answer="'+q[2]+'"><p>'+String(i+1)+'. '+q[0]+'</p>'+q[1].map(a=>'<label><input type="radio" name="teach-q'+i+'" value="'+a+'">'+a+'</label>').join('')+'<div class="quiz-feedback" data-note="'+q[3]+'"></div></article>').join('')+'</div>';
    panel.querySelectorAll('.teach-go').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.target)?.scrollIntoView({behavior:'smooth',block:'start'}));
    panel.querySelector('#teachPractice').onclick=downloadPractice;
    panel.querySelector('#teachDemo').onclick=()=>{if(!window.confirm(t.confirm))return;savedCase=snapshot();const set=(id,value)=>{const e=document.getElementById(id);if(e){e.value=value;e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));}};set('case','tri');document.getElementById('case')?.dispatchEvent(new Event('change',{bubbles:true}));set('qallow','0.080');set('hallow','1.00');document.getElementById('weirOn').checked=true;document.getElementById('oriOn').checked=false;['freeDischarge','freeTailwater','freeBackwater','freeSubmergence','freeOperation'].forEach(id=>{const e=document.getElementById(id);if(e){e.checked=true;e.dispatchEvent(new Event('change',{bubbles:true}));}});set('freeEvidenceRecord','教學假設：單一銳頂堰自由出流；不受尾水、回水、淹沒或操作控制影響。');set('screeningLimitRecord','教學假設：Qallow = 0.080 m³/s、Hallow = 1.00 m；僅供受限篩選操作練習。');document.getElementById('run')?.click();render();navButton();const note=document.createElement('div');note.className='status';note.textContent=t.demo;panel.appendChild(note);};
    panel.querySelector('#teachRestore').onclick=()=>{if(!savedCase)return;restore(savedCase);savedCase=null;document.getElementById('run')?.click();render();const note=document.createElement('div');note.className='status';note.textContent=t.restored;panel.appendChild(note);};
    panel.querySelectorAll('input[type=radio]').forEach(input=>input.onchange=()=>{const card=input.closest('.quiz-card'),out=card.querySelector('.quiz-feedback'),correct=input.value===card.dataset.answer;out.textContent=correct?'✓ '+card.dataset.note:'↻ '+card.dataset.note;out.className='quiz-feedback '+(correct?'ok':'bad');const n=[...panel.querySelectorAll('.quiz-card')].filter(c=>c.querySelector('input:checked')?.value===c.dataset.answer).length;panel.querySelector('#teachScore').textContent=t.score.replace('{n}',n);});
  }
  render();navButton();document.getElementById('lang')?.addEventListener('click',()=>setTimeout(()=>{render();navButton();},0));
})();
